// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    Reverter r;

    function setUp() public {
        c = new MyContract();
        r = new Reverter();
    }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        vm.deal(address(c), amount);
        bool ok;
        try c.sendTo(address(r), amount) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "sendTo to refusing receiver must revert");
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
